SELECT e.title, e.start_date, e.end_date
FROM exhibitions e
WHERE e.ticket_price IS NULL;

SELECT medium, COUNT(*) AS piece_count
FROM artworks
GROUP BY medium;

SELECT EXTRACT(YEAR FROM STR_TO_DATE(start_date, '%Y-%m-%d')) AS year, COUNT(*) AS exhibition_count
FROM exhibitions
GROUP BY year;

SELECT a.title, a.creation_year, a.medium, a.acquisition_cost
FROM artworks a
WHERE a.acquisition_cost > (SELECT AVG(acquisition_cost) FROM artworks);

SELECT p.name, p.species, p.breed, p.birth_date, p.weight_kg
FROM pets p
WHERE p.microchip_id IS NULL;

SELECT species, COUNT(*) AS pet_count
FROM pets
GROUP BY species;

SELECT city, COUNT(*) AS client_count
FROM owners
GROUP BY city;

SELECT species, AVG(weight_kg) AS avg_weight
FROM pets
GROUP BY species;

SELECT o.order_id, o.order_date, o.ship_date, o.status
FROM orders o
WHERE o.status = 'Pending' AND o.ship_date IS NULL;

SELECT DISTINCT c.business_name, c.customer_type, c.city, c.state
FROM customers c
WHERE c.credit_limit IS NULL;

SELECT p.name, p.country
FROM producers p
WHERE p.country = 'United States' AND p.organic_certified = 1;

SELECT DISTINCT customer_id, business_name, customer_type, city, state, account_opened, credit_limit 
FROM customers 
WHERE customer_id NOT IN (SELECT DISTINCT customer_id FROM orders);

SELECT customer_type, COUNT(*) AS customer_count
FROM customers
GROUP BY customer_type;

SELECT color, AVG(bottle_price) AS avg_bottle_price
FROM wines
GROUP BY color;

SELECT status, SUM(quantity) AS bottles_tied_up
FROM order_items
GROUP BY status;

SELECT DISTINCT c.full_name
FROM crew_members c
WHERE c.hire_date IS NULL;

SELECT shoot_days.shoot_date, shoot_days.notes
FROM shoot_days
WHERE shoot_days.weather_delay_hours > 1;

SELECT country, AVG(daily_rate) AS avg_daily_rate
FROM locations
GROUP BY country;

SELECT genre, COUNT(*) AS film_count, SUM(budget_usd) AS total_budget
FROM productions
GROUP BY genre;

SELECT shoot_date, scenes_completed, scenes_planned, (scenes_completed * 100.0 / scenes_planned) AS pct_done
FROM shoot_days
WHERE scenes_completed < scenes_planned;

SELECT c.full_name, c.day_rate
FROM crew_members c
WHERE c.day_rate > (SELECT AVG(day_rate) FROM crew_members);

SELECT t.turbine_id, t.turbine_tag, t.model, t.manufacturer, t.rated_kw, t.status
FROM turbines t
WHERE t.status = 'offline';

SELECT order_type, COUNT(*) AS job_count
FROM work_orders
GROUP BY order_type;

SELECT priority, AVG(labor_hours) AS avg_labor_hours
FROM work_orders
GROUP BY priority;

SELECT certification_level, COUNT(*) AS technician_count, AVG(hourly_rate) AS avg_hourly_pay
FROM technicians
GROUP BY certification_level;

SELECT t.full_name, t.hourly_rate
FROM technicians t
WHERE t.hourly_rate > (SELECT AVG(hourly_rate) FROM technicians);

SELECT c.case_number, c.filing_date
FROM cases c
WHERE c.status = 'open';

SELECT h.hearing_id, h.case_id, h.hearing_date, h.hearing_type, h.outcome, h.duration_minutes
FROM hearings h
WHERE h.duration_minutes > 100;

SELECT j.full_name, j.courtroom
FROM judges j
WHERE j.specialty IS NULL;

SELECT case_type, COUNT(*) AS case_count
FROM cases
GROUP BY case_type;

SELECT hearing_type, AVG(duration_minutes) AS avg_duration
FROM hearings
GROUP BY hearing_type;

SELECT d.delivery_id, d.supplier_id, d.material_id, d.delivery_date, d.weight_kg
FROM deliveries d
WHERE d.contamination_pct IS NULL;

SELECT m.material_name
FROM materials m
WHERE m.category = 'Metal' AND m.price_per_tonne > 1000;

SELECT batch_id, batch_date, line_name, supervisor, status
FROM processing_batches
WHERE status IN ('Rejected', 'In Progress');

SELECT supplier_type, COUNT(*) AS delivery_count
FROM deliveries
GROUP BY supplier_type;

SELECT line_name, COUNT(*) AS runs, SUM(input_kg) AS total_input_kg
FROM processing_batches
GROUP BY line_name;

SELECT s.title, s.language
FROM shows s
WHERE s.genre = 'technology';

SELECT DISTINCT s.company_name
FROM sponsors s
WHERE s.contact_email IS NULL;

SELECT s.title, h.full_name
FROM shows s
JOIN hosts h ON s.host_id = h.host_id;

SELECT language, AVG(duration_minutes) AS avg_duration
FROM episodes
GROUP BY language;

SELECT e.episode_id, e.title, e.downloads
FROM episodes e
WHERE e.downloads > (SELECT AVG(downloads) FROM episodes);

SELECT genre, COUNT(*) AS movie_count
FROM movies
GROUP BY genre;

SELECT payment_method, SUM(total_paid) AS total_money, COUNT(*) AS bookings_count
FROM bookings
GROUP BY payment_method;

SELECT m.title, m.imdb_score
FROM movies m
WHERE m.imdb_score > (SELECT AVG(imdb_score) FROM movies WHERE imdb_score IS NOT NULL);

SELECT name, vessel_type, home_port, length_m, gross_tonnage, year_built, status
FROM vessels
WHERE vessel_id NOT IN (SELECT DISTINCT vessel_id FROM trips);

SELECT vessel_type, COUNT(*) AS count
FROM vessels
GROUP BY vessel_type;

SELECT fishing_area, AVG(fuel_liters) AS avg_fuel_liters
FROM trips
GROUP BY fishing_area;

SELECT grade, AVG(price_per_kg) AS avg_price_per_kg
FROM catches
GROUP BY grade;
